const app=document.querySelector('#app'),nav=document.querySelector('#nav'),healthEl=document.querySelector('#health'),build=document.querySelector('#build');let health,catalog,lastRun;
const pages=[['CORE','workspace','总览'],['CORE','debugger','两阶段调试器'],['CORE','states','Patient Graph'],['CORE','policy','Action Policy'],['CORE','models','模型与 Provider'],['BENCHMARKS','medmemorybench','MedMemoryBench'],['BENCHMARKS','medlocomo','MedLoCoMo'],['BENCHMARKS','cpcdbench','CPCD-Bench'],['OPERATIONS','runs','Runs & Errors'],['OPERATIONS','experiments','Experiments']];
