const api=async(path,options={})=>{const r=await fetch(path,{headers:{'content-type':'application/json'},...options,body:options.body&&typeof options.body!=='string'?JSON.stringify(options.body):options.body});const x=await r.json();if(!r.ok)throw Object.assign(new Error(x.error||r.statusText),{detail:x.detail,run_id:x.run_id});return x;};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const js=x=>esc(JSON.stringify(x,null,2));const pill=(x,c=x)=>`<span class="pill ${c}">${esc(x)}</span>`;
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3500)}
function head(k,title,sub){document.querySelector('#eyebrow').textContent=k;document.querySelector('#title').textContent=title;document.querySelector('#subtitle').textContent=sub||'';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===location.hash.slice(1)));}
const card=(title,body,cls='span12')=>`<section class="card ${cls}"><h2>${title}</h2>${body}</section>`;
const details=(title,x,open=false)=>`<details ${open?'open':''}><summary>${title}</summary><pre>${js(x)}</pre></details>`;
