function medMemoryLatestExperimentView(experiment,noise){const mode=noise?'With noise / Mixed (M)':'Clean / Efficient (E)',setting=noise?'M':'E';if(!experiment)return card(`${mode} · 最新实验`,`<div class="empty">当前 Persona 还没有${noise?'加 Noise':'不加 Noise'}的 MedMemoryBench 实验。该表只会由相同 Noise 设置的实验更新。</div>`);const stats=MEDMEMORY_TASK_COLUMNS.map(column=>medMemoryTaskStats(experiment,column)),scored=stats.reduce((sum,item)=>sum+item.scored,0),average=scored?stats.reduce((sum,item)=>sum+(Number(item.score)||0)*item.scored,0)/scored:null,correct=stats.reduce((sum,item)=>sum+item.correct,0),wrong=stats.reduce((sum,item)=>sum+item.wrong,0),unscored=stats.reduce((sum,item)=>sum+item.unscored,0),config=experiment.config||{},start=Number(config.start_session||1),count=Number(config.session_count||1),end=start+Math.max(1,count)-1,created=experiment.created_at?new Date(experiment.created_at).toLocaleString('zh-CN',{hour12:false}):'—';return card(`${mode} · 最新实验`,`<div class="latest-experiment-head"><div><b>CareHarness · Persona ${esc(config.persona_id||1)}</b><div class="small muted">${esc(created)} · Session ${start}–${end} · ${esc(mode)} · ${pill(experiment.status)}</div></div><button class="secondary open-latest-medmemory" data-id="${esc(experiment.id)}">查看完整实验输出</button></div><div class="model-note"><span><b>Answer Model：</b>${esc(medMemoryModelLabel(config,'judge'))}</span><span><b>Official Judge：</b>${esc(medMemoryModelLabel(config,'scoring_judge'))}</span><span><b>Extractor / Router：</b>${esc(medMemoryModelLabel(config,'extractor'))} / ${esc(medMemoryModelLabel(config,'router'))}</span></div><div class="experiment-metrics medmemory-latest-metrics"><div><div class="metric">${medMemoryPercent(average)}</div>已计分题目平均分</div><div><div class="metric">${scored}/${Number(experiment.progress?.query_total||stats.reduce((sum,item)=>sum+item.total,0))}</div>已计分 / 总题数</div><div><div class="metric">${correct}</div>Judge 判定正确</div><div><div class="metric">${wrong}</div>Judge 判定错误</div><div><div class="metric">${unscored}</div>待评 / 不可评分</div></div><p class="small muted">本表只展示该 Persona 在 ${esc(mode)} 设置下的最新一次实验。Avg. 由已经产生数值分数的题目动态计算，题型不全时不代表六类完整得分。</p><div class="scroll literature-result-table"><table><thead><tr><th>运行</th><th>设置</th>${stats.map(stat=>`<th title="${esc(stat.label)}">${stat.short}</th>`).join('')}<th>Avg.</th></tr></thead><tbody><tr><td><code>${esc(experiment.id.slice(0,8))}</code></td><td>${setting}</td>${stats.map(stat=>`<td>${medMemoryScoreCell(stat)}</td>`).join('')}<td class="score-average"><b>${medMemoryPercent(average)}</b><br><span class="small muted">${scored} 题</span></td></tr></tbody></table></div><h3>六类 query 动态明细</h3><div class="scroll literature-result-table"><table><thead><tr><th>题型</th><th>官方 metric</th><th>完成 / 总数</th><th>已计分</th><th>正确</th><th>错误</th><th>待评 / 不可评</th><th>平均分</th></tr></thead><tbody>${stats.map(stat=>`<tr><td><b>${stat.short}</b><br><span class="small muted">${esc(stat.task)}</span></td><td>${esc(stat.metric)}</td><td>${stat.completed}/${stat.total}</td><td>${stat.scored}</td><td>${stat.correct}</td><td>${stat.wrong}</td><td>${stat.unscored}</td><td>${medMemoryPercent(stat.score)}</td></tr>`).join('')}</tbody></table></div>`)}
