 const refreshSuite=async()=>{if(!resultBox?.isConnected||location.hash.slice(1)!=='medmemorybench'||!activeId)return;try{await bindSuite(await api(`/api/matched-suites/${encodeURIComponent(activeId)}`))}catch(error){resultBox.innerHTML=`<div class="notice danger">${esc(error.message)}</div>`}};
