 target.querySelector('#retry-failed')?.addEventListener('click',async()=>{const next=await api(`/api/experiments/${x.id}/retry-failed`,{method:'POST',body:{}});location.hash='experiments';toast(`已按原数据范围、使用当前模型创建完整重跑实验 ${next.id}`)});
